ckpt = {'P1': [1, 7], 'P2': [2, 8], 'P3': [3, 11]}
msgs = [('m1','P1',4,'P2',5), ('m2','P2',6,'P3',9),
        ('m3','P3',5,'P1',6), ('m4','P1',7.2,'P2',7.6)]
crash = 13
idx = {p: len(c)-1 for p, c in ckpt.items()}
moved = True
while moved:
    moved = False
    for _, s, ts, r, tr in msgs:
        if ts > ckpt[s][idx[s]] and tr < ckpt[r][idx[r]]:
            idx[r] -= 1; moved = True
line = {p: ckpt[p][idx[p]] for p in ckpt}
print(sum(idx[p] != len(ckpt[p])-1 for p in ckpt))
print(*[line[p] for p in ckpt])
print(sum(crash - line[p] for p in ckpt))
